package com.muxigame.city;

import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;

/** Read-only tutorial; opening a chapter never executes a game action. */
public final class CityHelpScreen extends Screen {
    private static final String[][] CHAPTERS = {
        {"职业魔杖 · 极简", "1  选位置或选人", "拿复制魔杖：潜行右键地面选新建位置；潜行右键NPC选编辑目标；右键空气打开职业设计。", "2  选职业，再创建", "选择职业，可填姓名，再点创建或应用。普通右键方块仍打开原完整复制界面。", "3  看四项运行条件", "点“检查住房 / 粮箱 / 资金 / 启动”：缺住房就安排入住；缺粮箱就关联专用箱并实际放粮。", "4  资金和启动", "资金页查看真实账户；OP改款须手动发送命令。居民循环和城市维护分别开启，打开帮助或设置不会自动启动。", "5  复用同一套设计", "保存到魔杖；下次读取模板再创建。模板不带钱、物品、家庭和进度。返回设置后刷新检查即可。"},
        {"储存与家庭魔杖 · 极简", "储存：按这个顺序点", "拿NPC储存魔杖：先右键本城NPC，再右键其工作方块，最后右键32格内的NPC储藏箱。转绑工作点会重置转职熟练度，勿随意点别人的岗位。", "箱子还需要实际粮食", "普通箱不计入家庭储粮；专用箱每箱最多10份粮。绑定不会送粮，也不能把非空箱直接转给别家。职业设计的运行条件页也能直接关联粮箱。", "婚姻：先选两人", "拿婚姻魔杖依次右键两位同城成年NPC，再选恋爱、事实婚姻或法定婚姻。选“单身/解除关系”会解除当前关系，请看清目标。", "空气右键与返回", "右键空气重新打开已选NPC的设置；没选人就先右键NPC。工作时间、家庭关系在原页面调整，帮助页只讲操作，不改变任何数据。"},
        {"城市与建筑魔杖 · 极简", "1  划城市", "城市魔杖右键地面选第一角，潜行右键选第二角，右键空气确认范围和名称。", "2  登记房屋", "建筑魔杖同样选两角，右键空气登记房屋；在房屋属性中设置床位、安排住户。登记不等于已经建好或已经开工。", "3  查看与补齐", "信息魔杖→城市管理→城村经济登记，选择城市或村落；两处登记后可对接，登记不生成钱粮或启动模拟。NPC缺住房、粮箱、资金或未启动时，用复制魔杖的“检查住房 / 粮箱 / 资金 / 启动”直接跳转。", "4  启动前确认", "先放工作方块、专用粮箱并准备真实口粮与资金。居民循环和城市维护是两个独立开关；帮助和登记本身不会自动启用它们。"},
        {"职业NPC快捷设计", "先准备一次", "用城市沙盘登记范围，摆放本职业的工作方块、住房和NPC储藏箱。整个聚落的经济、口粮与运行开关只配置一次，不必给每个NPC重填一遍。", "复制魔杖的新入口", "右键空气打开职业设计。潜行右键地面选择新建位置，潜行右键NPC选择编辑目标。选择职业、可选填写姓名；聚落自动识别，32格内空闲工作点自动匹配。普通右键方块仍是原完整复制界面。", "保存和复用", "保存到魔杖：这根物品带上职业、男女、本地皮肤、作息与猎户范围。选中已有职业NPC后可取样，再用同一魔杖设置新NPC。用多根魔杖保存多个设计。模板不复制UUID、钱、物品、家庭、熟练度和饥饿；重复应用不会补钱或清除进度。", "缺条件时怎么办", "没有空闲工作点就先放对应工作方块；工匠需要登记完成、有空位的工坊。采购商、烘焙师、生产工坊还要有本城经济。界面会提示缺少的条件。保存设计不会恢复已暂停的模拟，新NPC也不会凭空获得生活资金。高级设计沿用原NPC魔杖、储存魔杖和工作时间页面。", "本轮可用职业", "农夫、家庭主妇/农妇、猎户、农村头人、采购商、烘焙师、工坊生产者、维修工匠和普通居民。守卫、法官、养殖户等未完成职业后续逐项接入。复杂战斗参数、自定义模型和动作继续使用原完整复制功能。"},
        {"职业、落成与公共粮食（0.8.14）", "先理解数据城市", "城市数据持续运作，NPC与方块是表现。离城仍生产、吃饭和修补已发现的损坏，回城分批同步；不强制加载区块。服务器关闭期间不补算。", "给NPC分工", "NPC魔杖→高级→阵营→个人基础生活→职业与修补。农民默认负责草方块、泥土、耕地、水（含流动水）、小麦（含种子补种）和堆肥桶。工匠负责没有被其他启用职业认领的方块；其他职业也可以打开工匠能力。效率为格/运行小时，优先级越大越先；同格只结算一次。", "落成与改建", "信息魔杖→城市管理→落成/修补/公共粮仓→城市落成。记录当前非空气方块，不记录箱内物品；之后按职业逐格恢复。小麦补种为幼苗，正常长大、水流变化、耕地干湿、堆肥进度不算损坏。新增建筑不自动拆除。改建前暂停修补，改完重新落成。", "集体口粮", "选择本城已登记的经营粮仓并启用集体口粮。旧生产、配送、分配与守卫工资结算在本城暂停。全城农民共同负责全城麦田，每人最多80格，不重复计算；每格每小时1小麦，3小麦自动制1面包。所有人共用口粮，不发工资，不派送货员。工匠不产粮，这一阶段维修不扣材料。", "数字怎样改", "职业和修补支持citymaintenance export/apply；落成基准、损坏与待落地修补都存档。个人食量仍可在基础生活页调整，经济JSON仍可编辑。旧稻米转为小麦，米饭转面包，种子转小麦种子；旧ID仅保留读档迁移，不再出现在创造物品栏或配方中。"},
        {"从一个人开始（0.8.11）", "城市与个人分开", "NPC魔杖的全局设置→城市设置管理城市；高级→阵营→NPC个人·基础生活只改当前NPC。旧混合界面已经删除，旧存档数据保留。", "只先理解吃饭与待遇", "NPC魔杖→高级→阵营→NPC个人·基础生活。无所属聚落时先绑定，再进入基础生活。设置每小时食量、可食用口粮物品、指定公共粮仓、待遇需求下限和上限、实际待遇。粮仓须先登记经营账户。保存需确认，只影响这个NPC。", "时间和默认值", "默认每小时2份，下限20、上限40，实际待遇30。小时按服务器正常20TPS运行60分钟计算（72000tick），不是游戏日夜中的小时；卡顿时按实际完成的tick推进，停服不补算。每分钟累计，2份即每30分钟取1份。实际待遇低于下限表示不足，达到上限表示满意，中间可以接受。", "粮食从哪里来", "指定粮仓按公粮领取，不扣钱、不派快递员、不凭空生成食物；缺粮记为不满，补粮后到下个领取时间恢复。基础模式暂停此人的复杂消费、欲望增长和自动迁出；原有工作与工资不变，旧城其他居民仍按原配置运行。离城运行仍需该城启用simulation。", "一步步往后做", "这一版只做个人。以后再增加家庭成员与共用粮食，最后让聚落汇总人口、口粮、农田产出。后两层尚未实施。数据仍可cityeconomy export/apply编辑；basicMode、foodPerHour、basicWarehouse、minNeed、maxNeed、baseComfort为主要字段。关闭生活结算即可暂停该人领粮。"},
        {"供应修复与岗位接任（0.8.10）", "商人离开后谁来卖粮", "logistics.supply启用后，shops保存独立商店委托。商人迁出或不可用时，从同城可工作的居民接任，最多每次修复3项报价。无候选人就等待，不生成NPC、不送货币；保留价格和仓库。", "先解决口粮与堵仓", "essentials中的商品缺少可销售库存时优先调拨，允许释放无人经营仓的保留量。stockCaps限制原料产出库存，overflowWarehouses指定同所有者周转仓；只搬现有物品，箱满会换目标或暂停。", "厨房转岗与维护工资", "kitchens登记实际厨房、配方、工资、周期和最大岗位数。按人口需求核算产能，优先空闲居民，其次库存充足行业；一次最多转岗1人，原岗位停用保留。新岗位等下期消耗实际原料、支付实际工资。standbyWagePercent是库存/原料待工维护工资比例，默认0；启用后由原雇主真金支付，雇主没钱或设施损坏不发。", "数据修改与减负", "全部字段位于logistics[城市UUID].supply，可用cityeconomy export/apply修改。capacityPercent为食品产能目标百分比，donorReserveCycles为转岗来源行业库存门槛，staffPeriodTicks为转岗间隔。每次物流周期至多一单，配送和劳动仍共用寻路预算；离城不加载实体区块。旧城默认不启用。"},
        {"配送与离城模拟（0.8.9）", "离开城市仍能运作", "启用simulation后，服务器运行期间，未加载的城市继续按原周期生产、发薪、消费、增长需求和结算治安；不加载区块、不运行NPC实体、不补服务器关机期间的时间。回城同步实物库存，需求本身保存在同一居民数据中。旧城市默认不开启。", "商人主动补货", "logistics配置商品、商人、目标库存、保留库存、最小及最大批量、费用。定期从同一经营者的积压仓调往缺货仓；只搬真实货，不创造货币。人物取货送货是表现，路径受阻不复制或撤销账目。不同所有者需要另行购销合同，本版内部配送不擅自转移其财产。", "人口变化与冲突", "emigrateAfter设定连续缺少基本口粮多少个消费周期后迁出，0关闭；默认96期，每2400tick至多迁出1人。迁出归档NPC与经济配置，个人余额保留，不产生尸体和掉落。实物与离城快照不一致时暂停该仓，拒绝覆盖；带特殊组件的物品不进入虚拟仓库。", "数据入口", "城市经济页显示后台生产/消费和配送累计。cityeconomy export导出simulation与logistics，可按revision应用；库存通过stockEdits的expected/desired修改，离城时也支持。stocks中physical为离城实物基线、goods为当前账面库存；不要随便删除pending快照，否则会破坏对账。"},
        {"自主城市与工作表现", "生产和动作分开", "0.8.8：经济按配置周期结算真实库存与工资；走路、挥手次数不增加收入。workVisual开启工作表现，战斗优先，未加载居民不工作。", "稻田和资源点", "水稻在湿润耕地自然生长。农民走到成熟稻株附近收割并直接补种，不生成掉落物。resourceSource可设rice、forestry、quarry，代表农田、经营林地、采石区的周期产能；不按单次动作扣资源方块。设施减少、仓满或欠薪会停产。", "长期观察", "信息魔杖查看城市，账本查看资金库存，NPC魔杖调整工作消费。/cityeconomy perf显示经济和工作计数。启用simulation后卸载区域也能进行数据结算；未启用离城模拟的城市在区块卸载后暂停。", "数据编辑", "cityeconomy export导出；生产新增workVisual和resourceSource，旧配置默认关闭。修改后按导出revision应用；删除stockEdits可避免覆盖实时库存。不要用循环命令补钱补库存掩盖短缺。"},
        {"治安、驻军与性能",
            "设置守卫", "旧版混合界面已移除；以下历史治安参数现通过经济JSON维护。先停用该NPC的生产岗位，再设为守卫。全城治安开启后，填写已有付款账户（城市财政或经营账户）、工资和周期。缺勤、死亡、未加载或欠薪者不给覆盖；工资真实到账。",
            "覆盖与现有赃物规则", "训练值、护甲和当前生命影响服务能力，人口增长会摊薄覆盖。现有赃物事件仍扣同一个city_law治安值；值勤只按每期恢复/衰减上限逐步靠近目标，不清空失窃历史。目击赃物的guardWitness仍在NPC背包设计中设置，城市守卫职务不改NPC战斗AI。",
            "治安不能消除不满", "稳定度仍由消费和财富结构计算。治安影响事件风险，强制管控也有代价。自然不满不会无限累积成高暴乱风险，外部冲击可突破保护。此版没有自动抓捕、巡逻寻路或生成暴乱实体。",
            "城市变大怎么办", "生产每tick最多2项，旧口粮与复杂消费各4项，分配和治安各1城；轮转公平结算，不补离线产量。全城方块统计仍共用4096格/tick预算。首次大城市扫描会分批完成；后台计算无需一直开界面。实际帧率还受NPC寻路、模型、区块和其他模组影响。"},
        {"NPC工作与生活（新）",
            "入口和保存", "旧版混合界面已移除，以下高级参数通过经济JSON维护。个人简单设置请使用阵营页→NPC个人·基础生活。先在阵营页绑定城市。可逐人改生产原料/产出/工资、每项消费数量和舒适需求；只有点击保存并看到回执才生效。",
            "消费扩张与收入", "启用复杂消费会停用该人的旧口粮，避免重复扣粮。必需品优先，从同城商人真实库存购买。每项缺货或缺钱独立失败。默认低于每期3整币收入时需求停滞，收入3时120期涨1，收入60时6期涨1；达到需求40/60/80逐步引入更高档商品。",
            "舒适与不满", "基础舒适度是手动环境加分，成功消费再加分；不是自动住房评分。舒适低于需求扣稳定贡献，普通不满最多-3、缺必需品-4；高于需求最多+3。财富结构压力最多20。自主运作最低稳定20，不会无限积累为高暴乱风险。高风险需要外部压力；当前没有暴乱攻击AI。",
            "分配者与数据", "生活页可标记分配者，城市分配页设置真实现金剩余的提取比例、周转金底线和富裕者晋升门槛；此页影响全城。无正剩余不分配，不印钱。工资和分配算收入，管理员注资/借款不算。全部字段可经济JSON导入导出；保存前自动备份。停用复杂消费后需自行重新启用旧口粮或新配置。"},
        {"先玩一次买卖",
            "1  找到演示商人", "联合测试世界已有经济试验城，面包商在 X356、Y-60、Z354 附近。走近后空手右键城市面包商，打开商店。其他世界需先配置商人。",
            "2  买一块面包", "查看余额和库存，点击买1：支付3整币，背包增加1面包，仓库减少1面包。演示玩家初始50整币，实际余额以界面为准。",
            "3  再卖回去", "背包保留普通面包，点击卖1：获得2整币，仓库增加1面包。完整买卖一轮会少1整币，这是买卖价差。",
            "4  看城市怎样运转", "信息魔杖右键→经济与库存，翻页看账户、任务和近期账目。演示任务约每分钟结算一次；缺原料会停产，向经营箱补普通小麦即可。"},
        {"认识三根魔杖",
            "城市魔杖：划城市", "右键地面选第一角，潜行并右键地面选第二角。右键空气打开选区设置。用于新建城市、纳入或排除区域。",
            "建筑魔杖：登记房子", "独立选两角后右键空气，调整高度并登记建筑。它与城市选区互不覆盖；登记不会替你建造方块。",
            "信息魔杖：看信息", "右键打开城市信息；潜行右键城市内方块可选中该城市。页面可查看居民、建筑、仓库、方块统计、经济和操作说明。",
            "如何获得", "管理员或测试服输入 /city give。生存合成：城市魔杖用书+木棍；建筑魔杖用砖+木棍；信息魔杖用书+指南针。潜行默认是Shift，以你的按键设置为准。"},
        {"从零划出城市",
            "1  在地面选两角", "拿城市魔杖，右键第一角，再潜行右键对角。自动高度会包含上方建筑，也可能包含树木。此时青色框只是草稿，城市还没有改变。",
            "2  确认高度和名称", "朝空气右键，检查最低Y、最高Y；需要时手动修改，再填写名称并新建城市。以后扩张用纳入城市，挖掉归属用排除城市。",
            "3  检查真实归属", "手持魔杖走近：绿色网格是实际城市空间，红色是排除空间，金色只是外包围盒。局部网格显示身边8格，完整范围可进城市管理的沙盘逐层查看。",
            "4  改错或删除", "信息魔杖→城市管理，可改名、撤销范围编辑或删除城市。删除需确认，只解除登记，不拆世界方块或删除NPC；有经济关联时先按提示清理。"},
        {"登记房子和居民",
            "1  登记建筑", "在城内用建筑魔杖选两角，右键空气调整高度，再填写建筑名称和用途。成功后城市信息中的建筑数增加；建筑不能互相重叠。",
            "2  绑定居民", "带NPC进入城内，在它附近打开信息魔杖→NPC绑定，从附近列表明确选择它。也可用NPC魔杖→高级→阵营→所属城市设置。",
            "3  绑定经营箱", "面对6格内的城内箱子或木桶，打开信息魔杖→仓库绑定。双箱的每半边是独立登记位置；把普通原料和商品实际放入箱内。",
            "4  登记不等于开工", "上述操作建立城市、建筑、居民和仓库的关系。新城不会自动产粮或发钱；管理员还需配置经营账户、生产任务、报价和口粮计划，见管理员配置章节。"},
        {"读懂经济与交易",
            "账户：谁的钱", "信息魔杖→经济与库存。玩家、NPC、经营者和城市各有账户；整币是记账货币，不会自动兑换绿宝石。新账户余额为0。",
            "库存：货在哪里", "库存来自绑定的真实箱子和木桶。你从箱里拿走商品，商人就会缺货。普通商品交易不接收带自定义名称、附魔等特殊组件的物品。",
            "买与卖：从玩家角度看", "买1：玩家付钱、拿货；卖1：玩家交货、收钱。每次1件，点击立即执行。钱不够、货不够或放不下时整笔拒绝。",
            "哪些NPC能交易", "只有显式配置了城市报价的NPC使用这套商店；它须存活、已加载、属于该城并在城内，玩家需走近。其他原有NPC商店保持原玩法。"},
        {"生产和吃饭怎样结算",
            "生产先检查条件", "启用的任务需要登记建筑、工人、雇主账户和经营仓库。每期检查设施方块、原料、成品空间及工资，全部满足才一起执行。",
            "面包坊的一次生产", "示例：箱内消耗3小麦，增加1面包；经营账户支付3整币工资给工人。拆掉任务要求的熔炉会停产，修复后还需等下一期。",
            "居民再购买口粮", "启用口粮计划后，居民支付3整币给经营者，仓库真实消耗1面包。这个示例中工人收入又用于吃饭，面包数量可能看似没变，请同时看小麦和账目。",
            "时间与当前边界", "普通模板每24000游戏tick一次，联合演示每1200tick一次（正常20TPS约1分钟）。停服不计时，未加载、死亡或离城时暂停该期，不补离线产量。本版不改变NPC生命或AI。"},
        {"遇到问题先看这里",
            "有框却没纳入城市", "青色是未应用草稿，金色只是包围盒。右键空气应用，再走近看绿色网格。想重选时重新选第一角；城市魔杖潜行右键空气可清空草稿。",
            "没有生产或没有账目", "先确认管理员已启用任务。再看经济与库存中的失败原因，依次检查工人、设施、普通原料、成品空间和雇主余额，修复后等待下一期。",
            "买卖失败或打不开", "先走近已配置的商人，确认NPC仍在城内。买东西检查玩家余额、库存、背包空间；卖东西检查普通商品、经营余额和仓库空间。",
            "统计、删除或数据报错", "方块统计在城市信息→方块统计，世界改动后刷新。删除被拒绝按提示解除经济引用和处理余额。数据版本冲突要重新导出，不能强行使用旧revision。"},
        {"管理员配置与数据",
            "1  准备关系和模板", "先登记城、建筑、NPC和仓库。用 /citydata list 找城市UUID，再 /citydata export 城市UUID registrations 导出登记中的ID。/cityeconomy template 城市UUID 建筑UUID 仓库UUID NPC_UUID 文件名 生成模板。命令需管理权限。",
            "2  修改并启用", "模板只写文件，不自动生效。到存档/city_settlements/economy/编辑JSON，检查账户余额、仓库经营者、生产配方、工资、报价和口粮计划，再将需要的enabled改为true。模板初始余额为0。",
            "3  应用和验证", "/cityeconomy apply 文件名 revision，revision用文件中的版本号。查看游戏回执，再打开经济与库存。修改现有经济先 /cityeconomy export 文件名，使用最新导出避免覆盖新变化。",
            "4  库存与扩展限制", "实物库存修改用stockEdits的expected和desired，库存变化会拒绝旧请求。管理员改款有审计。政策、税收、银行、城投债和动态价格尚未实现，当前仅预留付款接口。完整字段见模组README。"}
    };
    private final Screen parent;
    private int page=0, scroll, maxScroll,menuOffset;
    public CityHelpScreen(Screen parent){super(Component.literal("城市规划 · 操作说明"));this.parent=parent;}
    public static CityHelpScreen quick(Screen parent,String chapter){var screen=new CityHelpScreen(parent);for(int i=0;i<CHAPTERS.length;i++)if(CHAPTERS[i][0].equals(chapter)){screen.page=i;return screen;}throw new IllegalArgumentException("未知帮助章节："+chapter);}
    private void go(int chapter){page=chapter;scroll=0;maxScroll=0;rebuildWidgets();}
    private void button(String text,int x,int y,int w,Runnable action){addRenderableWidget(Button.builder(Component.literal(text),b->action.run()).bounds(x,y,w,20).build());}
    @Override protected void init(){
        int w=Math.min(width-24,520),x=(width-w)/2;
        if(page<0){
            int gap=8,bw=(w-gap)/2;
            int count=Math.max(2,((height-140)/24)*2);for(int i=menuOffset;i<Math.min(CHAPTERS.length,menuOffset+count);i++){final int chapter=i;int slot=i-menuOffset;button((i+1)+"  "+CHAPTERS[i][0],x+(slot%2)*(bw+gap),82+(slot/2)*24,bw,()->go(chapter));}
            if(menuOffset>0)button("前页",x,height-54,65,()->{menuOffset=Math.max(0,menuOffset-count);rebuildWidgets();});if(menuOffset+count<CHAPTERS.length)button("后页",x+w-65,height-54,65,()->{menuOffset+=count;rebuildWidgets();});
            button(parent==null?"返回游戏":"返回原页面",width/2-70,height-30,140,this::onClose);
        }else{
            int bw=(w-18)/4,y=height-30;
            addRenderableWidget(Button.builder(Component.literal("上一章"),b->go(page-1)).bounds(x,y,bw,20).build()).active=page>0;
            button("目录",x+bw+6,y,bw,()->go(-1));
            addRenderableWidget(Button.builder(Component.literal("下一章"),b->go(page+1)).bounds(x+2*(bw+6),y,bw,20).build()).active=page<CHAPTERS.length-1;
            button("返回",x+3*(bw+6),y,bw,this::onClose);
        }
    }
    @Override public void onClose(){minecraft.setScreen(parent);}
    @Override public void render(GuiGraphics g,int mx,int my,float partial){
        g.fill(0,0,width,height,0xff101923);int w=Math.min(width-24,520),x=(width-w)/2;
        g.drawString(font,page<0?"城市规划 · 操作说明":(page+1)+" / "+CHAPTERS.length+"  "+CHAPTERS[page][0],x,15,0xffedcf8c,false);
        if(page<0){
            g.drawString(font,"先看前3章极简操作；后面带旧版本号的是历史说明。",x,38,0xffdce5e8,false);
            g.drawString(font,"登记不会自动开工；当前缺项请看职业设计的运行条件。",x,55,0xffffc985,false);
        }else{
            int y=43-scroll;g.enableScissor(x,36,x+w,height-48);
            for(int i=1;i<CHAPTERS[page].length;i+=2){
                g.drawString(font,CHAPTERS[page][i],x,y,0xffedcf8c,false);y+=16;
                for(var line:font.split(Component.literal(CHAPTERS[page][i+1]),w)){g.drawString(font,line,x,y,0xffdce5e8,false);y+=13;}
                y+=16;
            }
            maxScroll=Math.max(0,y+scroll-(height-48));g.disableScissor();
            if(maxScroll>0)g.drawString(font,"滚轮阅读  "+(scroll>=maxScroll?"已到底":"下方还有内容"),x,height-43,0xff95bfc6,false);
        }
        super.render(g,mx,my,partial);
    }
    @Override public void renderBackground(GuiGraphics g,int x,int y,float partial){}
    @Override public boolean mouseScrolled(double x,double y,double dx,double dy){if(page>=0)scroll=Math.clamp(scroll-(int)(dy*26),0,maxScroll);return true;}
    @Override public boolean isPauseScreen(){return false;}
}
